const run = $input.first().json;
const discovered = run.discovered || {};
const jobs = discovered.jobs || [];
const processed = run.processed_items || [];
const outreach = run.recruiter_outreach || [];
const observations = run.page_observations || [];
const packetReady = processed.filter((item) => item.status === 'packet_ready');
const review = processed.filter((item) => item.status === 'manual_review' || item.status === 'scored');
const rejected = processed.filter((item) => item.status === 'rejected');
const failed = processed.filter((item) => item.status === 'failed');
const enqueuedJobs = jobs.filter((job) => job.queue_id);
const shouldNotify = Number(discovered.enqueued_count || 0) > 0 || processed.length > 0 || failed.length > 0;
const lines = [
  '**CareerSite AI agent run**',
  `Discovered: ${discovered.discovered_count || 0} | Analyzed: ${discovered.analyzed_count || 0} | Enqueued: ${discovered.enqueued_count || 0}`,
  `Processed: ${processed.length} | Packet ready: ${packetReady.length} | Review: ${review.length} | Rejected: ${rejected.length} | Failed: ${failed.length}`,
  `Watcher reviewed: ${observations.length} | Recruiter drafts: ${outreach.length}`,
];
if (enqueuedJobs.length) {
  lines.push('', '**High-fit jobs queued**');
  for (const job of enqueuedJobs.slice(0, 5)) {
    lines.push(`- ${job.score || 0}% ${job.verdict || ''}: ${job.company || 'Unknown'} | ${job.title || 'Unknown role'} | ${job.queue_id}`);
  }
}
if (processed.length) {
  lines.push('', '**Processed packets**');
  for (const item of processed.slice(0, 5)) {
    const pipeline = item.pipeline_result || {};
    const exportResult = item.export_result || {};
    const company = pipeline.company || 'Unknown company';
    const title = pipeline.title || 'Unknown role';
    const score = pipeline.base_score === undefined ? 'N/A' : `${pipeline.base_score}%`;
    const artifact = exportResult.tailored_resume_pdf_path || exportResult.tailored_resume_html_path || exportResult.packet_folder_path || '';
    lines.push(`- ${item.status}: ${company} | ${title} | ${score}${artifact ? ` | ${artifact}` : ''}`);
    if (item.error) lines.push(`  Error: ${item.error}`);
  }
}
if (observations.length) {
  lines.push('', '**Page watcher (third eye)**');
  for (const obs of observations.slice(0, 5)) {
    const o = obs.observation || {};
    const jd = o.jd || {};
    const sponsor = jd.sponsorship_note ? ` | ${jd.sponsorship_note}` : '';
    lines.push(`- ${o.page_type || 'unknown'} (${o.engine || 'heuristic'}): ${jd.company || 'Unknown'} | ${jd.role || ''}${sponsor}`);
  }
}
return [{ json: { ...run, should_notify: shouldNotify, discord_content: lines.join('\n').slice(0, 1900) } }];
